# ---------------------------------------------------------------------------
# Velu, with point evaluation  (see solve_composite_isogenies.sage)
# ---------------------------------------------------------------------------

def velu(E, T):
    """Separable isogeny phi : E -> E/<T>.  Returns (codomain, evaluate)."""
    a1, a2, a3, a4, a6 = E.a_invariants()
    assert (a1, a2, a3) == (_sage_const_0 , _sage_const_0 , _sage_const_0 ), "expected short Weierstrass form"
    Fld = E.base_field()
    O = E(_sage_const_0 )

    R, seen = [], set()
    Q = T
    while Q != O:
        if Q not in seen:
            R.append(Q)
            seen.add(Q)
            seen.add(-Q)
        Q = Q + T

    data = []
    v_sum = Fld(_sage_const_0 )
    w_sum = Fld(_sage_const_0 )
    for Q in R:
        xQ, yQ = Q.xy()
        gx = _sage_const_3  * xQ**_sage_const_2  + a4
        vQ = gx if yQ == _sage_const_0  else _sage_const_2  * gx       # 2-torsion is self-paired: no factor 2
        uQ = _sage_const_4  * yQ**_sage_const_2 
        data.append((xQ, uQ, vQ))
        v_sum += vQ
        w_sum += uQ + xQ * vQ

    Ecod = EllipticCurve(Fld, [a4 - _sage_const_5  * v_sum, a6 - _sage_const_7  * w_sum])
    kernel_x = {xQ for xQ, _, _ in data}

    def evaluate(P):
        if P == O:
            return Ecod(_sage_const_0 )
        x, y = P.xy()
        if x in kernel_x:
            return Ecod(_sage_const_0 )
        X = x
        dX = Fld(_sage_const_1 )
        for xQ, uQ, vQ in data:
            d = x - xQ
            d2 = d * d
            X += vQ / d + uQ / d2
            dX -= vQ / d2 + _sage_const_2  * uQ / (d2 * d)
        return Ecod(X, y * dX)               # Y = y * dX/dx (Velu is normalised)

    return Ecod, evaluate


def isogeny_chain(E, K, l, e, push=()):
    """
    Codomain of the degree l^e isogeny with kernel <K>, computed as e
    prime-degree steps.  Also pushes each point of `push` through the whole
    composition.  Returns (codomain, [images]).
    """
    assert K.order() == l**e, f"expected order {l}^{e}, got {factor(K.order())}"

    Ecur, Kcur = E, K
    pushed = list(push)
    for j in range(e):
        T = (l**(e - _sage_const_1  - j)) * Kcur
        assert T.order() == l

        Ecur, evaluate = velu(Ecur, T)
        pushed = [evaluate(X) for X in pushed]
        if j < e - _sage_const_1 :
            Kcur = evaluate(Kcur)
            assert Kcur.order() == l**(e - _sage_const_1  - j), "kernel order did not drop by l"

    return Ecur, pushed


# ---------------------------------------------------------------------------
# The two TODOs from source.sage
# ---------------------------------------------------------------------------

def gen_public_key(E, P, Q, s, l, e, push):
    """Secret s -> (codomain, images of the other party's torsion basis)."""
    K = P + s * Q
    return isogeny_chain(E, K, l, e, push=push)


def gen_shared_secret(E, imP, imQ, s, l, e):
    """Second leg: same secret s, applied to the received torsion images."""
    K = imP + s * imQ
    Ecod, _ = isogeny_chain(E, K, l, e)
    return Ecod.j_invariant()


