print(f"  Alice   EA : j = {EA.j_invariant()}")

# --- Bob: phiB : E0 -> EB, degree 3^eb, publishes images of the 2-torsion ---
EB, (imP2, imQ2) = gen_public_key(E0, P3, Q3, sB, _sage_const_3 , eb, push=[P2, Q2])
